model_name = "gpt2"  # You can choose other models like "bert-base-uncased", "t5-small", etc.
tokenizer = AutoTokenizer.from_pretrained(model_name)
model = AutoModelForCausalLM.from_pretrained(model_name)

def evolve_ai(prompt):
    """
    Evolve AI by generating a response based on the input prompt using the loaded model.

    Args:
        prompt (str): Input text to generate a response for.

    Returns:
        str: Generated response.
    """
    # Tokenize the input prompt
    inputs = tokenizer.encode(prompt, return_tensors="pt")
    
    # Generate a response from the model
    outputs = model.generate(inputs, max_length=100)
    
    # Decode the generated tokens to text
    response = tokenizer.decode(outputs[0], skip_special_tokens=True)
    
    return response

# Example usage of the evolve_ai function
